#!/usr/bin/env bash
# Generate a state's confirm-open SQL from the canonical template (PROJECT_PLAN §6.13's
# "same SQL, zero new code" made literal — TODO Track 2 expansion). The generated file is
# COMMITTED like confirm_open_ca.sql / confirm_open_ut.sql, so rebuild_legality.sh's
# confirm_open_*.sql glob and the runbooks keep working unchanged.
#
#   ./scripts/etl/gen_confirm_open.sh <nv|az|co|nm|or|id>   ->  scripts/etl/confirm_open_<st>.sql
#
# Per-state parameters (predicates verified live 2026-07-11; see DATA_SOURCE_INVESTIGATION.md):
#   * public_predicate — the GLOBAL POLICY (matching Utah's blanket 'Federal'): public-but-closed
#     classes (DOD/DOE/MIL) COUNT as public for the buffer. Closure is the classifier's job; the
#     cross-check only asks "is any public ownership near?" — excluding them would repaint land
#     around every base YELLOW-on-top-of-GREEN, which is noise, not safety.
#   * The carve (Utah pattern, generalized): everything NOT matching the public predicate —
#     affirmative Private, tribal, water, AND null/unknown — is subtracted from the 100 m public
#     buffer, so adjacency never blankets a known-not-public parcel.
#   * Metric buffering in EPSG:5070 (CONUS Albers) for all new states (CA=3310/UT=26912 keep
#     their original CRS choices). Sliver threshold 1000 m² — the SMA sources are GCDB/PLSS-grade
#     (between CA's generalized 2000 and UT's cadastral 500); tune per state if the reality
#     check shows noise.
set -euo pipefail
cd "$(dirname "$0")/../.."
source scripts/etl/registry_lib.sh   # per-state params come from etl/sources.json (§6.13)
ST="${1:-}"

# Per-state parameters now live in the registry (was a case block here). SRC is the source_key;
# CRS / buffer_m / sliver_min_m2 are registry fields (a coastal state can pick a different CRS
# without editing this template). Only sql:"generated" sources use this template — CA/UT keep
# their committed bespoke confirm_open_<st>.sql.
STU=$(echo "$ST" | tr '[:lower:]' '[:upper:]')
KEY=$(reg_key_for_state_role "$STU" confirm_open) \
  || { echo "usage: $0 <state with a template-generated confirm_open source, e.g. nv az co nm or id>" >&2; exit 2; }
[ "$(reg_sql "$KEY")" = "generated" ] \
  || { echo "ERROR: registry source '$KEY' for $STU has sql='$(reg_sql "$KEY")' (bespoke, committed) — not template-generated" >&2; exit 2; }
SRC="$KEY"
STAGING=$(reg_confirm "$KEY" staging)
PUB=$(reg_confirm "$KEY" public_predicate)
ATTR=$(reg_attribution "$KEY")
VINTAGE=$(reg_vintage "$KEY")
CRS=$(reg_confirm "$KEY" crs)
BUFFER=$(reg_confirm "$KEY" buffer_m)
SLIVER=$(reg_confirm "$KEY" sliver_min_m2)

cat > "scripts/etl/confirm_open_${ST}.sql" <<EOF
-- Confirm-Open step for ${STU} (PROJECT_PLAN §6.4.1/§6.13, decisions #30/#31; TODO Track 2).
-- GENERATED by scripts/etl/gen_confirm_open.sh ${ST} — edit the generator, not this file.
-- "GREEN must be earned": where PAD-US says open (GREEN) but the authoritative ${STU} ownership
-- layer (${ATTR}) shows NO public land within ~100m, the open status is unconfirmed -> YELLOW.
-- Buffer-carve (Utah pattern): parcels the source maps as NOT-public (private/tribal/water/null)
-- are carved back out of the buffer so adjacency never blankets a known-not-public parcel.
-- Prereq: ${STAGING} loaded (scripts/etl/pull_sma.sh ${ST}); legality_polygons built (unify.sql).
-- Idempotent: deletes prior ${SRC} rows first.
--
-- TARGET TABLE (review PP-8): reads and writes go to the psql variable :legality_tbl, defaulting
-- to the live tiles.legality_polygons. rebuild_legality.sh passes tiles.legality_polygons_new so
-- the whole sequence builds off to the side and reaches live only via atomic_swap after gating.
SET client_min_messages TO WARNING;

\if :{?legality_tbl}
\else
  \set legality_tbl tiles.legality_polygons
\endif

DELETE FROM :legality_tbl WHERE source_key = '${SRC}';

DROP TABLE IF EXISTS staging.conf_notpub_${ST};
-- SubDivide the not-public side too: wall-to-wall states (CO) have thousands of large private
-- multipolygons, and un-subdivided carve unions OOM-crashed the dev Postgres (2026-07-12).
-- Small pieces keep every LATERAL union local and bounded.
CREATE TABLE staging.conf_notpub_${ST} AS
  SELECT ST_SubDivide(ST_MakeValid(geom), 512) AS geom FROM ${STAGING}
  WHERE NOT (${PUB});
-- PARCEL-GRADE CARVE (Tier-1 validation finding, 2026-07-12): SMA sources are GCDB/PLSS-grade
-- and miss parcel-sized private inholdings inside blocks they map federal — the validation
-- caught 9 real false-GREENs in CO/NM cabin/ranch country. Where county parcel data is loaded
-- (staging.parcels), assessor-confirmed private parcels join the carve, giving those counties
-- Utah-grade resolution. No-op where staging.parcels is absent or has no rows for the state.
INSERT INTO staging.conf_notpub_${ST}
  SELECT ST_SubDivide(ST_MakeValid(geom), 512)
  FROM staging.parcels
  WHERE to_regclass('staging.parcels') IS NOT NULL
    AND state = '${STU}' AND owner_class = 'private';
CREATE INDEX conf_notpub_${ST}_gix ON staging.conf_notpub_${ST} USING GIST (geom);

DROP TABLE IF EXISTS staging.conf_buf_${ST};
CREATE TABLE staging.conf_buf_${ST} AS
  SELECT ST_CollectionExtract(ST_MakeValid(ST_Difference(b.geom,
           COALESCE(np.geom, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3) AS geom
  FROM (SELECT ST_Transform(ST_Buffer(ST_Transform(ST_SubDivide(ST_MakeValid(geom), 512), ${CRS}), ${BUFFER}), 4326) AS geom
        FROM ${STAGING}
        WHERE ${PUB}) b
  LEFT JOIN LATERAL (
    SELECT ST_Union(n.geom) AS geom FROM staging.conf_notpub_${ST} n WHERE ST_Intersects(n.geom, b.geom)
  ) np ON true;
CREATE INDEX conf_buf_${ST}_gix ON staging.conf_buf_${ST} USING GIST (geom);

INSERT INTO :legality_tbl
  (geom, verdict, reason, land_manager, unit_nm, protection_status, state_nm, data_vintage, source_key)
SELECT ST_Multi(d.geom), 'YELLOW',
  'Open status not confirmed by ${STU} public-ownership data (${ATTR}) — possibly private; verify before collecting.',
  NULL, NULL, 'unconfirmed-open', '${STU}', '${VINTAGE} (confirm-open vs PAD-US)', '${SRC}'
FROM (
  SELECT (ST_Dump(
            ST_CollectionExtract(
              ST_MakeValid(ST_Difference(g.geom,
                COALESCE(b.buf, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3))).geom AS geom
  FROM (SELECT ST_Subdivide(geom, 256) AS geom FROM :legality_tbl
        WHERE state_nm='${STU}' AND verdict='GREEN' AND source_key='padus') g
  LEFT JOIN LATERAL (
    SELECT ST_Union(cb.geom) AS buf FROM staging.conf_buf_${ST} cb WHERE ST_DWithin(cb.geom, g.geom, 0.003)
  ) b ON true
) d
WHERE d.geom IS NOT NULL AND NOT ST_IsEmpty(d.geom) AND ST_Area(d.geom::geography) > ${SLIVER};

SELECT count(*) AS unconfirmed_polys, round((sum(ST_Area(geom::geography))/1e6)::numeric, 2) AS km2
FROM :legality_tbl WHERE source_key = '${SRC}';
EOF
echo "wrote scripts/etl/confirm_open_${ST}.sql (source_key=${SRC})"
